import math

def find_solutions_very_wide():
    solutions = []
    ln2 = math.log(2)
    ln5 = math.log(5)

    # For e from -30 to 30, find d such that d*ln2 + e*ln5 \in (0, ln2)
    for e in range(-30, 31):
        d_min = math.ceil((-e * ln5) / ln2)
        d_max = math.floor((ln2 - e * ln5) / ln2)

        for d in range(d_min, d_max + 1):
            val = (2**d) * (5**e)
            if 1 < val < 2:
                X = 50 / (val - 1)
                if X.is_integer():
                    X_int = int(X)
                    Y_int = X_int + 50

                    def is_form(n):
                        if n <= 0: return False
                        while n % 2 == 0: n //= 2
                        while n % 5 == 0: n //= 5
                        return n == 1

                    if is_form(X_int) and is_form(Y_int):
                        solutions.append((X_int, Y_int))
    return list(set(solutions))

print(find_solutions_very_wide())

